        assert!(ccxt::runtime::is_true(&(Value::Bool(get_value(&get_value(&exchange.prop(&&Value::Str("urls".into())), &Value::Str("api".into())), &Value::Str("public".into())).as_str() == Some("https://testnet.org")))));
